SELECT      TRUNC(SYSDATE)                                       AS report_date,     so.STD_AV_IND                                        AS cost_method,     CASE so.STD_AV_IND         WHEN 'A' THEN 'Weighted Average Cost'         WHEN 'S' THEN 'Standard Cost'     END                                                  AS cost_method_desc,      p.HALF_NO                                            AS fiscal_half,     p.CURR_454_MONTH                                     AS fiscal_month_454,     p.CURR_454_WEEK                                      AS fiscal_week_454,     p.CURR_454_YEAR                                      AS fiscal_year_454,     ia.ID                                                AS adjustment_id,     ia.ADJ_DATE                                          AS adjustment_date,     TO_CHAR(ia.ADJ_DATE, 'YYYY-MM')                      AS adj_year_month,     TO_CHAR(ia.ADJ_DATE, 'YYYY-IW')                      AS adj_year_week,     ia.CREATE_DATETIME                                   AS created_datetime,     ia.CREATE_ID                                         AS created_by,     ia.USER_ID                                           AS adjusted_by,     ia.REASON                                            AS reason_code,     rt.REASON_DESC                                       AS reason_description,     r.COGS_IND                                           AS cogs_indicator,     CASE r.COGS_IND         WHEN 'Y' THEN 'Inventory Adjustment - COGS Impact'         WHEN 'N' THEN 'Inventory Adjustment - No COGS Impact'         ELSE 'N/A'     END                                                  AS tran_code_desc,      ia.LOCATION                                          AS location_id,     ia.LOC_TYPE                                          AS loc_type,     CASE ia.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'         WHEN 'E' THEN 'External Finisher'     END                                                  AS location_type_desc,     CASE ia.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS location_name,      im.DEPT                                              AS dept_no,     d.DEPT_NAME                                          AS dept_name,     d.PROFIT_CALC_TYPE                                   AS accounting_method,     CASE d.PROFIT_CALC_TYPE         WHEN 1 THEN 'Cost Method'         WHEN 2 THEN 'Retail Method'     END                                                  AS accounting_method_desc,     im.CLASS                                             AS class_no,     c.CLASS_NAME                                         AS class_name,     im.SUBCLASS                                          AS subclass_no,     sc.SUB_NAME                                          AS subclass_name,      ia.ITEM                                              AS item_id,     im.ITEM_DESC                                         AS item_description,     im.ITEM_NUMBER_TYPE                                  AS item_number_type,     im.STANDARD_UOM                                      AS uom,     im.PACK_IND                                          AS pack_ind,     im.WASTE_TYPE                                        AS waste_type,     CASE im.WASTE_TYPE         WHEN 'SP' THEN 'Spoilage Wastage'         WHEN 'SA' THEN 'Sales Wastage'         ELSE 'N/A'     END                                                  AS waste_type_desc,      ia.PREV_QTY                                          AS qty_before,     ia.ADJ_QTY                                           AS adj_qty,     (ia.PREV_QTY + ia.ADJ_QTY)                          AS qty_after,     CASE         WHEN ia.ADJ_QTY > 0 THEN 'Positive (Stock Gain)'         WHEN ia.ADJ_QTY < 0 THEN 'Negative (Stock Loss)'         ELSE 'Zero'     END                                                  AS adj_direction,     ia.ADJ_WEIGHT                                        AS adj_weight,     ia.ADJ_WEIGHT_UOM                                    AS adj_weight_uom,      ils.UNIT_COST                                        AS unit_cost,     ils.AV_COST                                          AS weighted_avg_cost,     ROUND(ia.ADJ_QTY * ils.AV_COST,   4)                AS adj_value_at_wac,     ROUND(ia.ADJ_QTY * ils.UNIT_COST, 4)                AS adj_value_at_unit_cost,      il.SELLING_UNIT_RETAIL                               AS unit_retail,     ROUND(ia.ADJ_QTY * il.SELLING_UNIT_RETAIL, 4)       AS adj_value_at_retail,      ils.STOCK_ON_HAND                                    AS current_soh,     (ils.STOCK_ON_HAND - ia.ADJ_QTY)                    AS soh_before_adj,     ils.STOCK_ON_HAND                                    AS soh_after_adj,      td.TRAN_DATE                                         AS ledger_tran_date,     td.TRAN_CODE                                         AS ledger_tran_code,     td.UNITS                                             AS ledger_units,     td.TOTAL_COST                                        AS ledger_total_cost,     td.TOTAL_RETAIL                                      AS ledger_total_retail,     td.AV_COST                                           AS ledger_av_cost,     td.ADJ_CODE                                          AS ledger_adj_code,     CASE td.ADJ_CODE         WHEN 'C' THEN 'Correction'         WHEN 'U' THEN 'Unit Adjustment'         WHEN 'A' THEN 'Adjustment'         ELSE td.ADJ_CODE     END                                                  AS ledger_adj_code_desc,     td.REF_NO_1                                          AS ledger_ref_no,      CASE         WHEN td.TRAN_CODE IS NOT NULL THEN 'MATCHED'         ELSE 'NO LEDGER ENTRY - INVESTIGATE'     END                                                  AS ledger_match_status,      ROUND(         NVL(td.TOTAL_COST, 0)         - ROUND(ia.ADJ_QTY * ils.AV_COST, 4)     , 4)                                                  AS cost_variance,      ia.COMMENTS                                          AS comments  FROM     MFCS_RDS.RDS_WV_INV_ADJ                  ia      LEFT JOIN MFCS_RDS.RDS_WV_INV_ADJ_REASON_TL  rt                                               ON  ia.REASON          = rt.REASON                                              AND  rt.LANG             = 1      LEFT JOIN MFCS_RDS.RDS_WV_INV_ADJ_REASON      r                                               ON  ia.REASON          = r.REASON      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER         im   ON  ia.ITEM       = im.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS                d    ON  im.DEPT       = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS               c    ON  im.DEPT       = c.DEPT                                                    AND  im.CLASS      = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS            sc   ON  im.DEPT       = sc.DEPT                                                    AND  im.CLASS      = sc.CLASS                                                    AND  im.SUBCLASS   = sc.SUBCLASS      LEFT JOIN MFCS_RDS.RDS_WV_STORE           st   ON  ia.LOCATION   = st.STORE                                                    AND  ia.LOC_TYPE   = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh   ON  ia.LOCATION   = wh.WH                                                    AND  ia.LOC_TYPE   = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH    ils  ON  ia.ITEM       = ils.ITEM                                                    AND  ia.LOCATION   = ils.LOC                                                    AND  ia.LOC_TYPE   = ils.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC         il  ON  ia.ITEM       = il.ITEM                                                    AND  ia.LOCATION   = il.LOC                                                    AND  ia.LOC_TYPE   = il.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_TRAN_DATA        td  ON  ia.ITEM       = td.ITEM                                                    AND  ia.LOCATION   = td.LOCATION                                                    AND  ia.LOC_TYPE   = td.LOC_TYPE                                                    AND  td.TRAN_CODE  IN (22, 23)                                                    AND  TRUNC(td.TRAN_DATE)                                                         = TRUNC(ia.ADJ_DATE)      LEFT JOIN MFCS_RDS.RDS_WV_PERIOD            p   ON  TRUNC(ia.ADJ_DATE)                                                         = TRUNC(p.VDATE)      CROSS JOIN MFCS_RDS.RDS_WV_SYSTEM_OPTIONS  so  WHERE     ia.ADJ_DATE >= ADD_MONTHS(SYSDATE, -3)   ORDER BY     ia.ADJ_DATE    DESC,     ia.LOCATION,     ia.REASON,     ia.ITEM